// The window list: every open window of the layout, grouped by type, with the registered types
// that have none; a row focuses its window, floats or tiles it, closes it; a type opens a new
// window. It is a window itself (a Frame, opened once), and the search and the folded groups
// live in its config, so they survive with it.
//
// Search tokens, space separated, all must match: `term` (substring of the title or the type),
// `tile` / `float` (the mode), `focused`. Service windows may be opened and closed here too.
import { useEffect, useReducer } from 'react'
import type { ReactElement } from 'react'
import type { TilrPluginObject, WindowMode, WindowRow, WindowType } from 'tilr'
import { mount, useCtx, useWindow, windowRoot } from 'tilr/react'
import { Frame } from 'tilr/ui'

/** The window's config: what survives with it. */
interface Config { query: string, closed: string[] }

const MODES: readonly WindowMode[] = ['tile', 'float']

const css = `
  .winlist { display: flex; flex-direction: column; gap: 6px; height: 100%; }
  .winlist input[type=search] { box-sizing: border-box; width: 100%; font: inherit; color: inherit;
    background: var(--bg); border: 1px solid var(--line); border-radius: var(--radius); padding: 2px 6px; }
  .winlist input[type=search]:focus { outline: none; border-color: var(--accent); }
  .winlist ul { list-style: none; margin: 0; padding: 0; }
  .winlist .group > .head { display: flex; gap: 6px; align-items: baseline; padding: 4px 0 2px; cursor: default; user-select: none; }
  .winlist .group > .head .arrow { width: 10px; color: var(--muted); font-size: 10px; }
  .winlist .group > .head .count { color: var(--muted); font-size: 10px; flex: 1; }
  .winlist .group > .head button { padding: 0 6px; line-height: 1.3; }
  .winlist .group.closed > ul { display: none; }
  .winlist .group > ul { padding-left: 16px; }
  .winlist .row { display: grid; grid-template-columns: 10px minmax(0, 1fr) auto auto auto; gap: 8px; align-items: center; padding: 2px 0; cursor: default; }
  .winlist .row:hover .name { color: var(--accent); }
  .winlist .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--line); }
  .winlist .dot.focused { background: var(--accent); }
  .winlist .name { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .winlist .mode { color: var(--muted); font-size: 10px; }
  .winlist .row button { padding: 0 5px; line-height: 1.3; }
  .winlist .row .blank { width: 21px; }
  .winlist .empty { color: var(--muted); padding: 4px 0; }
`

// predicates and groups are exported for the unit tests (index.test.ts, run under Node: nothing
// at the top level of this file touches the DOM). The plugin is the default export.

/** Parses the query into predicates. Every predicate must hold for a row to show. */
export function predicates(query: string): ((w: WindowRow) => boolean)[] {
  return query.toLowerCase().split(/\s+/).filter(Boolean).map(token => {
    if ((MODES as readonly string[]).includes(token)) return w => w.mode === token
    if (token === 'focused') return w => w.focused
    return w => w.title.toLowerCase().includes(token) || w.type.toLowerCase().includes(token)
  })
}

/** The rows that pass `query`, by type, in the order the types were registered, then the types
 *  with no window (so that one can be opened); a type that is not registered comes last. With
 *  a query, types without a match are left out. */
export function groups(rows: WindowRow[], types: string[], query: string): { type: string, rows: WindowRow[] }[] {
  const tests = predicates(query)
  const shown = rows.filter(w => tests.every(test => test(w)))
  const byType = new Map<string, WindowRow[]>()
  for (const type of types) byType.set(type, [])
  for (const w of shown) byType.set(w.type, [...byType.get(w.type) ?? [], w])
  return [...byType].filter(([, list]) => !query.trim() || list.length).map(([type, list]) => ({ type, rows: list }))
}

/** Any registered type can be opened; singleton enforcement belongs to layout. */
export function openable(def: WindowType | undefined): boolean {
  return !!def
}

/** Service lifetime does not prevent the user from closing its window. */
export function closable(def: WindowType | undefined): boolean {
  void def // All windows are user-closable, including legacy service windows.
  return true
}

/** What the list draws of the windows, as one string: the list is drawn again when this
 *  changes, not on every change of the layout (a float dragged, a split moved: rects it does
 *  not show). */
export function shown(rows: WindowRow[], title: (id: string) => string | undefined): string {
  return JSON.stringify(rows.map(w => [w.id, w.type, w.title, w.mounted, w.mode, w.modes.length, w.focused, w.mode === 'nested' && w.parent ? title(w.parent) ?? null : null]))
}

function Windows(): ReactElement {
  const ctx = useCtx()
  // Its own config (the search, the folded groups); the others' windows below; the types
  // changing is the third case.
  const win = useWindow<Config>(['config'])
  const [, bump] = useReducer((n: number) => n + 1, 0)
  useEffect(() => {
    const off = ctx.on('windows/change', bump)
    bump()   // a type may have come or gone between the render and this subscription
    return () => { off() }
  }, [ctx])

  const config: Config = { query: win.config?.query ?? '', closed: win.config?.closed ?? [] }
  const closed = new Set(config.closed)
  const set = (patch: Partial<Config>) => win.setConfig({ ...config, ...patch })
  const rows = ctx.layout.list()
  const title = (id: string) => ctx.layout.get(id)?.title
  const drawn = shown(rows, title)
  // Every change of the layout, drawn again only when what the list shows differs from what it
  // drew; checked once per burst of changes (a microtask: React draws later anyway), and once on
  // subscribing (a change between the render and the subscription).
  useEffect(() => {
    let queued = false
    let live = true
    const check = () => { if (live && shown(ctx.layout.list(), title) !== drawn) bump() }
    check()
    const off = win.subscribe(() => {
      if (queued) return
      queued = true
      queueMicrotask(() => { queued = false; check() })
    })
    return () => { live = false; off() }
  })
  const list = groups(rows, ctx.windows.list(), config.query)

  return (
    <Frame>
      <div className="winlist">
        <input type="search" placeholder="search" spellCheck={false} value={config.query} onChange={e => set({ query: e.target.value })} />
        <ul className="tree">
          {list.map(({ type, rows }) => {
            const def = ctx.windows.get(type)
            const fold = closed.has(type) && rows.length > 0
            return (
              <li key={type} className={fold ? 'group closed' : 'group'}>
                <div className="head" onClick={() => set({ closed: fold ? config.closed.filter(t => t !== type) : [...config.closed, type] })}>
                  <span className="arrow">{rows.length ? (fold ? '▸' : '▾') : ''}</span>
                  <span className={def ? 'label' : 'label muted'}>{type}</span>
                  <span className="count">{rows.length}</span>
                  {openable(def) && <button title={`open a ${type}`} data-call="layout.open" onClick={e => { e.stopPropagation(); ctx.layout.open({ type }) }}>+</button>}
                </div>
                <ul>
                  {rows.map(w => (
                    <li key={w.id} className="row" data-window-row={w.id} onClick={() => ctx.layout.focus(w.id)}>
                      <span className={w.focused ? 'dot focused' : 'dot'} />
                      <span className="name" title={w.mounted ? w.title : `${w.title} (waiting for ${w.type})`}>{w.title}</span>
                      <span className="mode">{w.mode === 'nested' ? `in ${(w.parent && ctx.layout.get(w.parent)?.title) ?? '?'}` : w.mode}</span>
                      {w.modes.length > 1
                        ? <button title={w.mode === 'float' ? 'tile' : 'float'} data-call={w.mode === 'float' ? 'layout.tile' : 'layout.float'} onClick={e => { e.stopPropagation(); w.mode === 'float' ? ctx.layout.tile(w.id) : ctx.layout.float(w.id) }}>⧉</button>
                        : <span className="blank" />}
                      {closable(def)
                        ? <button title="close" data-call="layout.close" onClick={e => { e.stopPropagation(); ctx.layout.close(w.id) }}>×</button>
                        : <span className="blank" />}
                    </li>
                  ))}
                </ul>
              </li>
            )
          })}
          {!list.length && <li className="empty">{rows.length ? 'nothing matches' : 'no windows'}</li>}
        </ul>
      </div>
    </Frame>
  )
}

// The object form, not definePlugin(): windowRoot() takes the whole Context.
export default {
  name: 'windows',
  author: 'tilr',
  tags: ['chrome'],
  version: __TILR_VERSION__,
  inject: ['ui', 'windows', 'layout'],
  apply(ctx) {
    ctx.ui.style(css)
    ctx.windows.register<Config>('windows', {
      title: 'windows',
      defaultConfig: { query: '', closed: [] },
      mount: (host, win) => mount(host, windowRoot(ctx, win, <Windows />)),
    })
  },
} satisfies TilrPluginObject
